// === Tab: mySketch ===
//For the #wccChallenge on the theme of "improbable architecture" ----> code by Aaron Reuland
//Part of me wonders why I often make 3D(-ish) pictures with 2D code.
//Could I have made this easier/more 'realistic' in WEBGL? maybe...
//but I guess feel I have more direct control over the look of the thing this way, and I feel more a part of
//the tradition of 2D drawing and painting and instead of 3D sculpture.
//Drawing inspiration from a newfound love of the painter František Kupka (paricularly 'le jaillissement II')
//with the pillar shapes.
//Uses Zaron Chen(ZRNOF)'s  p5.flex library to add responsiveness.

let palettes=[
	//except for the 1st palette, colors drawn from photos taken by me while on daily walks
	['#eef5db','#c7efcf','#a09654','#924f11','#290300'],
		//frosted fall leaf
	['#cac9cc','#758f96','#393c25','#bc3e10','#5f2223'],
	//rusted tank
	['#b3b082','#fcb86a','#904a00','#6f4e12','#4c2500'], 
	//lichen, silvery wooden bench
	['#f1ec78','#85b19f','#6d5456','#3d4f49','#3b3c41'],
	//woodland floor, gentle
	['#edd4aa','#c19964','#a67448','#857c33','#775834']

]

let colors

let simplex

function setup() {
	simplex= openSimplexNoise(Date.now())
	createCanvas(windowWidth, windowWidth/2);
	colors= random(palettes)
	background(colors[3]);


	for(let i=0; i<30; i++){
		tower(random(width), height*1.2, random(width/30, width/15))
	}
	let bgFade= color(colors[3])
	bgFade.setAlpha(220)
	background(bgFade)


	tower(width*0.66, height*1.2, width/20)
	bgFade.setAlpha(50)
	background(bgFade)
	bridge(random(10000))

	tower(width-width/12, height*1.2, width/9)
	bridge(random(10000))

	tower(width/8, height*1.2, width/8)

	flex({
    canvas: {
       fit: SCALE_DOWN
    }
  })
}



function tower(x, h, baseW) {
	push()
	stroke(0, 15)
	translate(x, height)
	let n = noise(x / 20, -height / 100)
	next = map(sin(-height / 50 + n + x / 50), -1, 1, h / 100, h / 3)
	for (let y = -h; y < 0; y += next) {
		n = noise(x, y / 50)
		next = map(sin(y / 50 + n + x / 50), 1, -1, h / 100, h / 3)
		let w = map(sin(y / 50 + n + x / 50), -1, 1, baseW * 0.75, baseW * 2)
		push()
		translate(w / 6, -w / 6)

		let f = floor(constrain((map(sin(y / 50 + n + x / 50), -1, 1, 0, colors.length - 1)), 0, colors.length - 1))
		let fr = fract(constrain((map(sin(y / 50 + n + x / 50), -1, 1, 0, colors.length)), 0, colors.length))
		let c1 = color(colors[f])
		let c2 = color(colors[f + 1])
		let filler = lerpColor(c1, c2, fr)
		fill(filler)
		let ll = createVector(cos(-PI - PI / 6) * (w * 0.66), y + next + sin(-PI - PI / 6) * (w * 0.66))
		quad(0, y, cos(-PI - PI / 6) * (w * 0.66), y + sin(-PI - PI / 6) * (w * 0.66), ll.x, ll.y, 0, y + next)
		fill(255, 40)
		quad(0, y, cos(-PI - PI / 6) * (w * 0.66), y + sin(-PI - PI / 6) * (w * 0.66), ll.x, ll.y, 0, y + next)
		fill(filler)
		quad(0, y + next, ll.x, ll.y, ll.x + cos(PI / 6) * (w * 0.33), ll.y + sin(PI / 6) * (w * 0.33), cos(PI / 6) * (w * 0.33), y + next + sin(PI / 6) * (w * 0.33))
		fill(0, 60)
		quad(0, y + next, ll.x, ll.y, ll.x + cos(PI / 6) * (w * 0.33), ll.y + sin(PI / 6) * (w * 0.33), cos(PI / 6) * (w * 0.33), y + next + sin(PI / 6) * (w * 0.33))
		fill(filler)
		quad(0, y, cos(PI / 6) * (w * 0.33), y + sin(PI / 6) * (w * 0.33), cos(PI / 6) * (w * 0.33), y + next + sin(PI / 6) * (w * 0.33), 0, y + next)
		pop()

	}
	pop()
}


function bridge(seed){
	let bricks=[]
 stroke(0, 15)

	for(let x=-width*0.2; x<=width*1.2; x+=10){
		let y= map(simplex.noise2D(x/width, seed), -1, 1, height, 0)
		let xoff= map(simplex.noise2D(y/500, seed), -1, 1, -width/5, width/5)
		bricks.push(createVector(x+xoff, y))
	}

	let p= floor(random(bricks.length/3, bricks.length*0.66))
for(let i=bricks.length-2; i>=0; i--){
	let beg= bricks[i]
	let end= bricks[i+1]

	if(i==p){
		person(beg.x, beg.y)
	}
	  var n = simplex.noise3D(beg.x/500, beg.y / 500, seed*10)
	  var f = floor(constrain(map(n, -1, 1, 0, colors.length - 1), 0, colors.length ))
		var fr = fract(constrain(map(n, -1, 1, 0, colors.length-1), 0, colors.length))
		var c1 = color(colors[f])
		var c2 = color(colors[f + 1])
		var filler = lerpColor(c1, c2, fr)
		fill(filler)

	noStroke()

	let begarch= map(abs(beg.x-width/2), width/2, 0, height/4, height/25)
	let endarch= map(abs(end.x-width/2), width/2, 0, height/4, height/25)
	let begThick= map(noise(beg.x/100, beg.y/100, seed),0, 1, begarch, begarch/3) 
	let endThick= map(noise(end.x/100, end.y/100, seed), 0, 1, endarch, endarch/3)
	quad(beg.x, beg.y, beg.x, beg.y+begThick, end.x, end.y+endThick, end.x, end.y)
	quad(beg.x, beg.y+begThick, end.x, end.y+endThick, end.x+cos(-PI-PI/6)*endThick/3, end.y+endThick+sin(-PI-PI/6)*endThick/3,beg.x+cos(-PI-PI/6)*endThick/3, beg.y+begThick+sin(-PI-PI/6)*endThick/3 )
	fill(0, 50)
	quad(beg.x, beg.y+begThick, end.x, end.y+endThick, end.x+cos(-PI-PI/6)*endThick/3, end.y+endThick+sin(-PI-PI/6)*endThick/3,beg.x+cos(-PI-PI/6)*endThick/3, beg.y+begThick+sin(-PI-PI/6)*endThick/3 )
  fill(100)
	quad(beg.x, beg.y+begThick, beg.x+cos(-PI-PI/6)*endThick/3, beg.y+begThick+sin(-PI-PI/6)*endThick/3, beg.x+cos(-PI-PI/6)*endThick/3, beg.y+begThick/3+sin(-PI-PI/6)*endThick/3, beg.x, beg.y)		

}	
}

function person(x, y){
	push()
	fill('#290300')
	stroke('#290300')
	let yer=y-height/60
	let ph= height/20
	rectMode(CENTER)
	ellipse(x, yer-ph/4, ph/9, ph/7)
	rect(x, yer, ph/5, ph/3, 10)
	rect(x-ph/18, yer+ph/4, ph/17, ph/3)
	rect(x+ph/18, yer+ph/4, ph/17, ph/3)
	push()
	translate(x-ph/20, yer-ph/18)
	rotate(PI/10)
	rect(0, 0, ph/18, ph/4)
	pop()

	pop()
}

